function update(dt){if(!gameOn)return;dt=Math.min(dt,.035);worldTime+=dt;if(toastTimer>0&&((toastTimer-=dt)<=0))ui.toast.classList.remove('show');player.attack=Math.max(0,player.attack-dt);player.spell=Math.max(0,player.spell-dt);player.dodge=Math.max(0,player.dodge-dt);player.inv=Math.max(0,player.inv-dt);player.will=Math.min(100,player.will+dt*5.2);player.walk+=dt*8;oilTime=Math.max(0,oilTime-dt);
let canMove=mode==='explore'||mode==='hunt',dx=canMove?((keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)):0,dy=canMove?((keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)):0,len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.face=Math.atan2(dy,dx);}let speed=player.dodge>0?590:235,ease=player.dodge>0?1:Math.min(1,dt*12);player.vx+=(dx*speed-player.vx)*ease;player.vy+=(dy*speed-player.vy)*ease;if(!len&&player.dodge<=0){player.vx*=Math.max(0,1-dt*10);player.vy*=Math.max(0,1-dt*10);}player.x=Math.max(65,Math.min(W-65,player.x+player.vx*dt));player.y=Math.max(80,Math.min(H-70,player.y+player.vy*dt));if(mouse.down&&performance.now()-lastAttack>450){attack();lastAttack=performance.now();}
